from PIL import Image
import numpy as np
from scipy import ndimage as ndi
im=np.array(Image.open('/app/target.png').convert('L'))<80
L,n=ndi.label(im,structure=np.ones((3,3)))
def hull(points):
 pts=sorted(set(map(tuple,points)))
 def cr(o,a,b):return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
 lo=[]
 for p in pts:
  while len(lo)>=2 and cr(lo[-2],lo[-1],p)<=0:lo.pop()
  lo.append(p)
 up=[]
 for p in pts[::-1]:
  while len(up)>=2 and cr(up[-2],up[-1],p)<=0:up.pop()
  up.append(p)
 return lo[:-1]+up[:-1]
for i,s in enumerate(ndi.find_objects(L)):
 if s:
  y,x=s; area=(L[s]==i+1).sum()
  if area<500 and area>40:
   pts=np.argwhere(L==i+1)[:,::-1]
   print('bbox',x.start,x.stop-1,y.start,y.stop-1,'area',area,'hull',hull(pts))
